int handle_incoming_packet(int s, unsigned char* data, int len, struct sockaddr_in* s_in) {
    if (len == 5 && memcmp(data, "sorbo", 5) == 0) {
        // Prepare and send an internet check command
        const char* response = "ICHECK";
        if (sendto(s, response, strlen(response), 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }
        return 0;
    } else {
        // Extract packet ID and length (assuming they are at fixed positions)
        if (len < 6) {
            return 1; // Not enough data to extract ID and length
        }

        int packet_id = *(int*)(data);
        int packet_len = *(int*)(data + 4);

        // Check for duplicate packet IDs
        static int last_id = 0;
        if (packet_id <= last_id) {
            return 1; // Duplicate or invalid packet ID
        }
        last_id = packet_id;

        // Send back processed data
        if (sendto(s, data, packet_len, 0, (struct sockaddr*)s_in, sizeof(*s_in)) < 0) {
            return 1;
        }

        // Handle packet ID wrapping
        if (last_id >= INT_MAX - 1000) {
            last_id = 0; // Reset to 0 if threshold is reached
        }

        return 0;
    }
}

